import React, { useState } from 'react';
import { 
  User, Settings, ShieldCheck, Map, Wallet, 
  BookOpen, Globe, Award, Camera, Save, 
  Clock, Mail, Phone, ChevronRight
} from 'lucide-react';

export default function StudentDashboard() {
  // Mock initial state - In a real app, this would come from a database
  const [isEditing, setIsEditing] = useState(false);
  const [profile, setProfile] = useState({
    firstName: "Juan",
    lastName: "Dela Cruz",
    email: "juan.delacruz@university.edu.ph",
    phone: "+63 912 345 6789",
    avatar: "https://api.dicebear.com/7.x/avataaars/svg?seed=Juan",
    bio: "Sophomore Computer Science student focused on AI and accessibility.",
    interests: ["Artificial Intelligence", "Community Development", "Web Technologies"]
  });

  // AI-Derived Recommendations (Mocking data that would come from the AI Engine)
  const aiInsights = {
    status: "Stable",
    riskScore: 12,
    recommendations: [
      {
        id: 1,
        title: "Government Subsidy Path",
        description: "Based on your income bracket, you qualify for the Tertiary Education Subsidy (TES).",
        icon: <Wallet className="text-emerald-500" />,
        action: "Apply Now"
      },
      {
        id: 2,
        title: "Digital Inclusion Program",
        description: "Your area shows limited connectivity. You are eligible for a free mobile data allowance.",
        icon: <Globe className="text-indigo-500" />,
        action: "Claim Data"
      },
      {
        id: 3,
        title: "Peer Mentorship",
        description: "Your high study time score makes you a great candidate to lead peer study groups.",
        icon: <Award className="text-amber-500" />,
        action: "Learn More"
      }
    ]
  };

  const handleSave = (e) => {
    e.preventDefault();
    setIsEditing(false);
    // Logic to update backend would go here
  };

  return (
    <div className="max-w-6xl mx-auto space-y-8 animate-in fade-in duration-700">
      
      {/* HEADER SECTION */}
      <div className="flex flex-col md:flex-row gap-8 items-start">
        
        {/* PROFILE CARD (Customizable) */}
        <div className="w-full md:w-1/3 bg-white rounded-[2.5rem] border border-slate-100 shadow-xl overflow-hidden">
          <div className="h-32 bg-gradient-to-r from-indigo-600 to-violet-600"></div>
          <div className="px-6 pb-8">
            <div className="relative -mt-16 mb-4 flex justify-center">
              <img 
                src={profile.avatar} 
                alt="Profile" 
                className="w-32 h-32 rounded-3xl border-4 border-white bg-slate-50 shadow-lg object-cover"
              />
              <button 
                onClick={() => setIsEditing(!isEditing)}
                className="absolute bottom-0 right-1/4 bg-white p-2 rounded-xl shadow-md border hover:bg-slate-50 transition-all"
              >
                <Settings size={16} className="text-slate-600" />
              </button>
            </div>

            {isEditing ? (
              <form onSubmit={handleSave} className="space-y-4">
                <input 
                  type="text" 
                  value={profile.firstName}
                  onChange={(e) => setProfile({...profile, firstName: e.target.value})}
                  className="w-full p-3 bg-slate-50 border rounded-xl font-bold"
                  placeholder="First Name"
                />
                <textarea 
                  value={profile.bio}
                  onChange={(e) => setProfile({...profile, bio: e.target.value})}
                  className="w-full p-3 bg-slate-50 border rounded-xl text-sm"
                  rows="3"
                />
                <button type="submit" className="w-full bg-indigo-600 text-white py-3 rounded-xl font-bold flex items-center justify-center gap-2">
                  <Save size={18} /> Save Changes
                </button>
              </form>
            ) : (
              <div className="text-center">
                <h2 className="text-2xl font-black text-slate-800">{profile.firstName} {profile.lastName}</h2>
                <p className="text-slate-400 font-medium text-sm mb-4">{profile.email}</p>
                <div className="flex justify-center gap-2 mb-6">
                  {profile.interests.map(tag => (
                    <span key={tag} className="px-3 py-1 bg-indigo-50 text-indigo-600 text-[10px] font-black uppercase rounded-full tracking-wider">
                      {tag}
                    </span>
                  ))}
                </div>
                <div className="space-y-3 text-left border-t pt-6">
                  <div className="flex items-center gap-3 text-slate-500 text-sm">
                    <Phone size={16} /> {profile.phone}
                  </div>
                  <div className="flex items-center gap-3 text-slate-500 text-sm">
                    <Clock size={16} /> Joined Semester 1, 2024
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* AI INTERACTIVE ROADMAP */}
        <div className="w-full md:w-2/3 space-y-6">
          
          {/* AI STATUS BANNER */}
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="p-4 bg-green-50 rounded-2xl text-green-500">
                <ShieldCheck size={32} />
              </div>
              <div>
                <h3 className="text-xl font-black text-slate-800">Your Success Roadmap</h3>
                <p className="text-slate-500 text-sm">AI-analyzed socioeconomic standing: <span className="text-green-600 font-bold uppercase">{aiInsights.status}</span></p>
              </div>
            </div>
            <div className="hidden sm:block text-right">
              <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Risk Level</p>
              <p className="text-2xl font-black text-indigo-600">{aiInsights.riskScore}%</p>
            </div>
          </div>

          {/* RECOMMENDATIONS GRID */}
          <h4 className="text-xs font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Recommended Interventions & Actions</h4>
          <div className="grid gap-4">
            {aiInsights.recommendations.map((rec) => (
              <div key={rec.id} className="group bg-white p-6 rounded-3xl border border-slate-100 hover:border-indigo-200 hover:shadow-md transition-all flex items-center gap-6">
                <div className="p-4 bg-slate-50 rounded-2xl group-hover:scale-110 transition-transform">
                  {rec.icon}
                </div>
                <div className="flex-1">
                  <h5 className="font-bold text-slate-800 mb-1">{rec.title}</h5>
                  <p className="text-sm text-slate-500 leading-relaxed">{rec.description}</p>
                </div>
                <button className="flex items-center gap-2 text-indigo-600 font-bold text-sm hover:translate-x-1 transition-all">
                  {rec.action} <ChevronRight size={16} />
                </button>
              </div>
            ))}
          </div>

